import java.util.*;import java.time.*;import java.net.*;import java.net.http.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.web.server.LocalServerPort;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.crypto.password.PasswordEncoder;import tools.jackson.databind.json.JsonMapper;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"dreamcore.tasks.agent-mode=off","dreamcore.tasks.enabled=true","dreamcore.tasks.initial-delay-ms=3600000","dreamcore.knowledge.initial-delay-ms=3600000","dreamcore.object-lifecycle.enabled=false","dreamcore.departure.worker-enabled=false"})
class FeedbackAdjustmentIntegrationTest {
 @Autowired JdbcTemplate db;@Autowired FeedbackService feedback;@Autowired RecommendationService recommendations;@Autowired DocumentService documents;@Autowired DocumentPublicationService publications;@Autowired PasswordEncoder passwords;@Autowired ObjectLifecycleService objects;@Autowired ObjectCleanupService cleanup;@Autowired ObjectScopeLifecycle scopes;@Autowired MaterialLifecycleService materials;@Autowired MaterialCleanupService materialCleanup;@Autowired ExperienceService experiences;@Autowired EvaluationAccess evaluation;@LocalServerPort int port;
 UUID tenant,author,reader,other,admin,privateSpace,readerSpace,shared,conversation,task;DocumentPublicationService.Publication publication;final String password="Synthetic-publication-feedback-password";final JsonMapper json=new JsonMapper();
 @Autowired com.dreamcore.workspace.feedbackadjustment.FeedbackAdjustmentService adjustments; @Autowired com.dreamcore.workspace.conversation.ConversationService conversations; @Autowired com.dreamcore.workspace.briefing.BriefingService briefing;
 @BeforeEach void setup(){tenant=UUID.randomUUID();author=UUID.randomUUID();reader=UUID.randomUUID();other=UUID.randomUUID();admin=UUID.randomUUID();privateSpace=UUID.randomUUID();readerSpace=UUID.randomUUID();shared=UUID.randomUUID();conversation=UUID.randomUUID();task=UUID.randomUUID();
  db.update("INSERT INTO tenants(id,name) VALUES (?,'合成副本反馈')",tenant);
  for(UUID a:List.of(author,reader,other,admin)){db.update("INSERT INTO accounts(id,email,display_name,password_hash) VALUES (?,?,?,?)",a,a+"@publication-feedback.test","合成用户",passwords.encode(password));db.update("INSERT INTO tenant_memberships(tenant_id,account_id,role) VALUES (?,?,?)",tenant,a,a.equals(admin)?"TENANT_ADMIN":"MEMBER");}
  db.update("INSERT INTO workspaces(id,tenant_id,owner_id,name,kind) VALUES (?,?,?,'作者私人','PERSONAL'),(?,?,?,'读者私人','PERSONAL'),(?,?,?,'共享发布','SHARED')",privateSpace,tenant,author,readerSpace,tenant,reader,shared,tenant,admin);
  for(UUID a:List.of(author,reader,other))db.update("INSERT INTO workspace_members(tenant_id,workspace_id,account_id,can_maintain) VALUES (?,?,?,?)",tenant,shared,a,a.equals(author));
  db.update("INSERT INTO conversations(id,tenant_id,workspace_id,owner_id,title) VALUES (?,?,?,?,'合成发布源')",conversation,tenant,privateSpace,author);
  db.update("INSERT INTO conversation_tasks(id,tenant_id,workspace_id,conversation_id,requested_by,prompt,mode,status,revision,attempt,reply,execution_class,finished_at) VALUES (?,?,?,?,?,'作者私人提示绝不开放','AGENT','SUCCEEDED',3,1,'合成发布正文：资料仅供流程验证。','verification',now())",task,tenant,privateSpace,conversation,author);
  var d=documents.create(author,tenant,conversation,task,null,UUID.randomUUID());publication=publications.publish(author,tenant,d.document().id(),1,UUID.randomUUID(),shared,null,null,null,"docx",true);
 }
 @AfterEach void finish(){db.update("UPDATE conversation_tasks SET status='CANCELLED' WHERE tenant_id=? AND status IN('QUEUED','RUNNING')",tenant);db.update("DELETE FROM login_attempts WHERE bucket=?",IdentityService.hash("ip:127.0.0.1"));}
 FeedbackService.Target target(UUID who){return recommendations.list(who,tenant,null,0,20,null).items().stream().filter(i->i.content().kind().equals("PUBLICATION")).findFirst().orElseThrow().feedbackTarget();}
 FeedbackService.Target businessTarget(){return new FeedbackService.Target("BRIEFING",task,3,1,"briefing-basic-v1",0);}
 com.dreamcore.workspace.feedbackadjustment.FeedbackAdjustmentService.Send body(UUID key,FeedbackService.Target t,int thread,int feedback,String message){return new com.dreamcore.workspace.feedbackadjustment.FeedbackAdjustmentService.Send(key,t,thread,feedback,message);}
 int count(String table){return db.queryForObject("SELECT count(*) FROM "+table+" WHERE "+(table.equals("feedback_adjustment_threads")?"tenant_id":"tenant_id")+"=?",Integer.class,tenant);}
 @Test void openingIsReadOnlyAndSendingCreatesOnePrivateActualWaitingTask(){var t=businessTarget();var open=adjustments.open(author,tenant,t,0,20);assertNull(open.threadId());assertEquals(0,count("feedback_entries"));assertEquals(0,count("feedback_adjustment_threads"));var sent=adjustments.send(author,tenant,body(UUID.randomUUID(),t,0,0,"把本卡先给结论，再列依据"));assertEquals("WAITING_CAPABILITY",sent.message().status());assertEquals("MODEL_NOT_CONFIGURED",sent.message().waitReason());assertEquals("NOT_USEFUL",sent.feedback().assessment().rating());assertEquals(1,sent.feedback().revision());assertNotEquals(conversation,sent.conversationId());assertEquals("BRIEFING_ADJUSTMENT",db.queryForObject("SELECT purpose FROM conversations WHERE id=?",String.class,sent.conversationId()));assertFalse(conversations.list(author,tenant,0,50).items().stream().anyMatch(c->c.id().equals(sent.conversationId())));assertEquals(0,db.queryForObject("SELECT attempt FROM conversation_tasks WHERE id=?",Integer.class,sent.message().taskId()));assertTrue(db.queryForObject("SELECT EXISTS(SELECT 1 FROM adjustment_task_dependencies WHERE task_id=? AND source_task_id=?)",Boolean.class,sent.message().taskId(),task));assertThrows(IdentityException.class,()->adjustments.open(other,tenant,t,0,20));}
 @Test void concurrentReplayAndOptimisticRevisionAreAtomic()throws Exception{var t=businessTarget();UUID key=UUID.randomUUID();var b=body(key,t,0,0,"同一次发送");try(var pool=Executors.newFixedThreadPool(2)){var replies=pool.invokeAll(List.<Callable<com.dreamcore.workspace.feedbackadjustment.FeedbackAdjustmentService.Sent>>of(()->adjustments.send(author,tenant,b),()->adjustments.send(author,tenant,b)));assertEquals(replies.getFirst().get(),replies.getLast().get());}assertEquals(1,count("feedback_entries"));assertEquals(2,count("conversation_tasks"));assertEquals("ADJUSTMENT_CHANGED",assertThrows(IdentityException.class,()->adjustments.send(author,tenant,body(UUID.randomUUID(),t,0,1,"旧窗口"))).code);var first=adjustments.open(author,tenant,t,0,20);db.update("UPDATE conversation_tasks SET status='QUEUED',execution_class='verification',wait_reason=NULL WHERE id=?",first.items().getFirst().taskId());assertEquals("CONVERSATION_BUSY",assertThrows(IdentityException.class,()->adjustments.send(author,tenant,body(UUID.randomUUID(),t,1,1,"等待期间不能生成半份评价"))).code);assertEquals(1,feedback.lookup(author,tenant,t).feedback().revision());assertEquals(1,adjustments.open(author,tenant,t,0,20).threadRevision());}
 @Test void laterReadVersionReusesThreadButEverySnapshotAndHistoryDependencyStayExact(){var t=businessTarget();var first=adjustments.send(author,tenant,body(UUID.randomUUID(),t,0,0,"首次建议"));db.update("UPDATE conversation_tasks SET status='SUCCEEDED',reply='合成调整结果',execution_class='verification',attempt=1,revision=2,finished_at=now() WHERE id=?",first.message().taskId());UUID later=UUID.randomUUID();db.update("INSERT INTO conversation_tasks(id,tenant_id,workspace_id,conversation_id,requested_by,prompt,mode,status,revision,attempt,reply,execution_class,finished_at) VALUES (?,?,?,?,?,'合成新卡','AGENT','SUCCEEDED',3,1,'第二版业务卡正文','verification',now())",later,tenant,privateSpace,conversation,author);var newTarget=new FeedbackService.Target("BRIEFING",later,3,1,"briefing-basic-v1",0);var next=adjustments.send(author,tenant,body(UUID.randomUUID(),newTarget,1,0,"这是第二版的调整说明"));assertEquals(first.threadId(),next.threadId());assertEquals(first.conversationId(),next.conversationId());assertEquals(2,next.threadRevision());var all=adjustments.open(author,tenant,newTarget,0,20).items();assertEquals(t,all.getFirst().reading().target());assertEquals("合成发布正文：资料仅供流程验证。",all.getFirst().reading().excerpt());assertEquals(newTarget,all.getLast().reading().target());assertEquals(List.of(first.message().taskId()),next.message().historyTaskIds());assertTrue(db.queryForObject("SELECT prompt FROM conversation_tasks WHERE id=?",String.class,next.message().taskId()).contains("合成调整结果"));assertEquals(2,db.queryForObject("SELECT count(*) FROM adjustment_task_dependencies WHERE task_id=?",Integer.class,next.message().taskId()));}
 @Test void independentPublicationAdjustmentNeverDependsOnPrivateAuthorTask(){var t=target(reader);var sent=adjustments.send(reader,tenant,body(UUID.randomUUID(),t,0,0,"这张发布卡需要说明数据期间"));assertEquals(shared,sent.message().reading().workspaceId());assertEquals("PUBLICATION",sent.message().reading().cardKind());assertEquals(0,db.queryForObject("SELECT count(*) FROM adjustment_task_dependencies WHERE task_id=?",Integer.class,sent.message().taskId()));assertEquals(List.of(publication.materialVersionId()),db.queryForList("SELECT version_id FROM feedback_task_sources WHERE task_id=?",UUID.class,sent.message().taskId()));db.queryForList("SELECT scrub_lifecycle_object('TASK',?)",task);assertEquals(1,adjustments.open(reader,tenant,t,0,20).items().size());assertFalse(json.writeValueAsString(sent).contains("作者私人"));db.update("DELETE FROM workspace_members WHERE workspace_id=? AND account_id=?",shared,reader);assertThrows(IdentityException.class,()->adjustments.open(reader,tenant,t,0,20));assertEquals(0,db.queryForObject("SELECT count(*) FROM readable_source_tasks WHERE id=?",Integer.class,sent.message().taskId()));assertThrows(IdentityException.class,()->adjustments.send(reader,tenant,body(UUID.randomUUID(),t,1,1,"撤权后不发送")));}
 @Test void clearingSourceActuallyErasesCapturedSnapshotHistoryAndDerivedTasks(){var t=businessTarget();var first=adjustments.send(author,tenant,body(UUID.randomUUID(),t,0,0,"不可残留的第一条私人说明"));var second=adjustments.send(author,tenant,body(UUID.randomUUID(),t,1,1,"不可残留的第二条私人说明"));db.queryForList("SELECT scrub_lifecycle_object('TASK',?)",task);for(var m:List.of(first.message(),second.message())){assertEquals("{}",db.queryForObject("SELECT snapshot::text FROM feedback_adjustment_messages WHERE id=?",String.class,m.id()));assertEquals("",db.queryForObject("SELECT request_text FROM feedback_adjustment_messages WHERE id=?",String.class,m.id()));assertEquals("PURGED",db.queryForObject("SELECT state FROM object_lifecycle WHERE kind='TASK' AND object_id=?",String.class,m.taskId()));assertEquals(0,db.queryForObject("SELECT count(*) FROM readable_source_tasks WHERE id=?",Integer.class,m.taskId()));}assertThrows(IdentityException.class,()->adjustments.open(author,tenant,t,0,20));}
 @Test void withdrawingOpinionDoesNotCancelAlreadyExplicitWorkOrRewriteOriginalMessage(){var t=businessTarget();var first=adjustments.send(author,tenant,body(UUID.randomUUID(),t,0,0,"最初明确说明"));feedback.edit(author,tenant,first.feedback().id(),UUID.randomUUID(),1,null,true);var view=adjustments.open(author,tenant,t,0,20);assertEquals("最初明确说明",view.items().getFirst().request());assertEquals("WAITING_CAPABILITY",view.items().getFirst().status());assertEquals(2,view.feedbackRevision());assertEquals("CONVERSATION_PURPOSE_MISMATCH",assertThrows(IdentityException.class,()->conversations.submit(author,tenant,first.conversationId(),privateSpace,UUID.randomUUID(),"绕过调整版本提交","AGENT")).code);}
 @Test void completedAdjustmentDoesNotEnterBusinessBriefingOrRecommendation(){var t=businessTarget();var sent=adjustments.send(author,tenant,body(UUID.randomUUID(),t,0,0,"调整表达"));db.update("UPDATE conversation_tasks SET status='SUCCEEDED',reply='合成排版修改',execution_class='verification',attempt=1,revision=3,finished_at=now() WHERE id=?",sent.message().taskId());assertFalse(briefing.list(author,tenant,null,"LATEST",null,"Asia/Shanghai",0,30).items().stream().anyMatch(c->c.taskId().equals(sent.message().taskId())));assertFalse(recommendations.list(author,tenant,null,0,20,null).items().stream().anyMatch(i->i.content().id().equals(sent.message().taskId())));assertEquals(0,db.queryForObject("SELECT count(*) FROM conversations WHERE purpose='BUSINESS' AND id=?",Integer.class,sent.conversationId()));}
 @Test void materialPurgeUsesRealCleanupAdapterAndDepartureScopeErasesOnlyOwner(){var target=target(reader);var sent=adjustments.send(reader,tenant,body(UUID.randomUUID(),target,0,0,"不能残留的副本调整"));db.update("INSERT INTO governance_capabilities(tenant_id,account_id,capability,workspace_id,granted_by) VALUES (?,?, 'LIFECYCLE_PURGE',?,?)",tenant,author,shared,admin);materials.act(author,tenant,shared,"MATERIAL",publication.materialId(),UUID.randomUUID(),0,"TRASH");assertThrows(IdentityException.class,()->adjustments.open(reader,tenant,target,0,20));materials.act(author,tenant,shared,"MATERIAL",publication.materialId(),UUID.randomUUID(),1,"PURGE");var job=materialCleanup.claim();assertNotNull(job);for(UUID object:materialCleanup.pending(job)){materialCleanup.remove(object);materialCleanup.removed(job,object);}materialCleanup.finish(job);assertEquals("{}",db.queryForObject("SELECT snapshot::text FROM feedback_adjustment_messages WHERE id=?",String.class,sent.message().id()));assertEquals("PURGED",db.queryForObject("SELECT state FROM object_lifecycle WHERE kind='TASK' AND object_id=?",String.class,sent.message().taskId()));}
 @Test void databaseWriteFailureRollsBackFeedbackTaskThreadAndReceipt(){var name="fail_adjustment_"+tenant.toString().replace("-","");db.execute("CREATE FUNCTION "+name+"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'synthetic write failure'; END $$");db.execute("CREATE TRIGGER "+name+" BEFORE INSERT ON feedback_adjustment_messages FOR EACH ROW EXECUTE FUNCTION "+name+"()");UUID key=UUID.randomUUID();var b=body(key,businessTarget(),0,0,"原子发送故障测试");try{assertThrows(RuntimeException.class,()->adjustments.send(author,tenant,b));assertEquals(0,count("feedback_entries"));assertEquals(1,count("conversation_tasks"));assertEquals(0,count("feedback_adjustment_threads"));assertEquals(0,db.queryForObject("SELECT count(*) FROM identity_requests WHERE actor_id=? AND request_id=?",Integer.class,author,key));}finally{db.execute("DROP TRIGGER "+name+" ON feedback_adjustment_messages");db.execute("DROP FUNCTION "+name+"()");}assertEquals("WAITING_CAPABILITY",adjustments.send(author,tenant,b).message().status());}
 @Test void fullLengthUserMessageFitsBoundedInternalContextButOrdinaryApiStillRejectsIt(){var t=businessTarget();var sent=adjustments.send(author,tenant,body(UUID.randomUUID(),t,0,0,"明".repeat(1900)));int size=db.queryForObject("SELECT length(prompt) FROM conversation_tasks WHERE id=?",Integer.class,sent.message().taskId());assertTrue(size>2000);assertTrue(size<=12000);assertThrows(IdentityException.class,()->conversations.submit(author,tenant,null,privateSpace,UUID.randomUUID(),"明".repeat(2001),"AGENT"));}
 @Test void departureIsolationAndPurgeErasePrivateAdjustmentButPreservePublishedSharedAsset(){var t=target(reader);var sent=adjustments.send(reader,tenant,body(UUID.randomUUID(),t,0,0,"离职私人调整内容"));UUID scope=UUID.randomUUID();Instant due=Instant.now().minusSeconds(1);scopes.isolateScope(tenant,reader,scope,due.minusSeconds(60),due,100);assertTrue(conversations.detail(reader,tenant,sent.conversationId(),0,20).tasks().getFirst().sourcesUnavailable());assertThrows(IdentityException.class,()->conversations.action(reader,tenant,sent.conversationId(),sent.message().taskId(),UUID.randomUUID(),sent.message().taskRevision(),"RESUME"));scopes.purgeScope(tenant,reader,scope,100);UUID record=db.queryForObject("SELECT id FROM object_lifecycle WHERE kind='TASK' AND object_id=?",UUID.class,sent.message().taskId());cleanup.clean(record);assertEquals("{}",db.queryForObject("SELECT snapshot::text FROM feedback_adjustment_messages WHERE id=?",String.class,sent.message().id()));assertEquals(1,db.queryForObject("SELECT count(*) FROM active_materials WHERE id=?",Integer.class,publication.materialId()));}
 @Test void explicitUsefulOptimizationDoesNotTurnExistingPositiveFeedbackIntoNegative(){var t=businessTarget();var original=feedback.create(author,tenant,UUID.randomUUID(),t,new FeedbackService.Assessment("USEFUL",List.of(),""));var sent=adjustments.send(author,tenant,new com.dreamcore.workspace.feedbackadjustment.FeedbackAdjustmentService.Send(UUID.randomUUID(),t,0,1,"内容有帮助，只调整表达","USEFUL"));assertEquals(original.id(),sent.feedback().id());assertEquals("USEFUL",sent.feedback().assessment().rating());assertEquals(2,sent.feedback().revision());assertThrows(IdentityException.class,()->adjustments.send(author,tenant,new com.dreamcore.workspace.feedbackadjustment.FeedbackAdjustmentService.Send(UUID.randomUUID(),t,1,2,"未选择评分",null)));}
 final class Client{final HttpClient http=HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();HttpResponse<String> send(String method,String path,Object body,boolean csrf)throws Exception{var r=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+path)).header("Content-Type","application/json");if(csrf){var c=json.readTree(send("GET","/api/v1/auth/csrf",null,false).body());r.header(c.get("headerName").asString(),c.get("token").asString());}return http.send(r.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofString());}}
 @Test void actualHttpOpenSendConflictAndCsrfUseRealContract()throws Exception{var c=new Client();assertEquals(200,c.send("POST","/api/v1/auth/login",Map.of("email",author+"@publication-feedback.test","password",password),true).statusCode());var t=businessTarget();String root="/api/v1/tenants/"+tenant+"/feedback-adjustments";String query="?kind=BRIEFING&taskId="+task+"&taskRevision=3&attempt=1&presentationVersion=briefing-basic-v1&presentationRevision=0";assertEquals(200,c.send("GET",root+query,null,false).statusCode());assertEquals(0,count("feedback_entries"));var response=c.send("POST",root,body(UUID.randomUUID(),t,0,0,"真实 HTTP 发送"),true);assertEquals(201,response.statusCode(),response.body());var result=json.readTree(response.body());assertEquals("WAITING_CAPABILITY",result.get("message").get("status").asString());var conflict=c.send("POST",root,body(UUID.randomUUID(),t,0,1,"旧版"),true);assertEquals(409,conflict.statusCode(),conflict.body());assertEquals("1.0",json.readTree(conflict.body()).get("contractVersion").asString());assertEquals(403,c.send("POST",root,body(UUID.randomUUID(),t,1,1,"无CSRF"),false).statusCode());}
}
